import{_ as a,o as r,c as t,a2 as i}from"./chunks/framework.BXzK3EA4.js";const h=JSON.parse('{"title":"Next.js 知识体系","description":"React 全栈框架,支持 SSR / SSG / ISR / CSR,内置 App Router、Server Components、Server Actions。","frontmatter":{},"headers":[],"relativePath":"前端/nextjs/index.md","filePath":"前端/nextjs/index.md","lastUpdated":1793932732000}'),o={name:"前端/nextjs/index.md"};function l(s,e,n,d,c,S){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="next-js-知识体系" tabindex="-1">Next.js 知识体系 <a class="header-anchor" href="#next-js-知识体系" aria-label="Permalink to &quot;Next.js 知识体系&quot;">​</a></h1><blockquote><p>React 全栈框架,支持 SSR / SSG / ISR / CSR,内置 App Router、Server Components、Server Actions。</p></blockquote><h2 id="📚-章节列表" tabindex="-1">📚 章节列表 <a class="header-anchor" href="#📚-章节列表" aria-label="Permalink to &quot;📚 章节列表&quot;">​</a></h2><ol><li><a href="./1-rendering-modes">渲染模式详解</a> — SSR / SSG / ISR / CSR 对比、按场景选型</li><li><a href="./2-app-router">App Router(重点)</a> — app/ 目录 / layout / loading / error / 路由组</li><li><a href="./3-data-fetching">数据获取</a> — fetch 缓存策略 / revalidate / Server Component 数据流</li><li><a href="./4-server-actions">Server Actions</a> — 表单提交 / 变更操作 / revalidatePath</li><li><a href="./5-api-routes">API Routes</a> — Route Handlers / GET POST / 中间件</li><li><a href="./6-styling">样式方案</a> — CSS Modules / Tailwind / CSS-in-JS / 全局样式</li><li><a href="./7-pages-router">Pages Router(需了解)</a> — pages/ 目录 / getStaticProps / getServerSideProps</li><li><a href="./8-project-structure">项目结构最佳实践</a> — 路由组 / app/ 布局 / 文件组织</li><li><a href="./9-middleware">Middleware 中间件</a> — 鉴权 / A/B 测试 / 多语言 / 安全头</li><li><a href="./10-caching">缓存机制</a> — Data Cache / Full Route Cache / revalidateTag</li><li><a href="./11-deployment">部署方案</a> — Vercel / Docker / 自建 / Cloudflare</li><li><a href="./12-testing">测试 - Vitest + Playwright</a> — 单元测试 / E2E / Server Component</li><li><a href="./13-resources">学习资源</a> — 官方文档 / 实战项目</li></ol><h2 id="📝-小结" tabindex="-1">📝 小结 <a class="header-anchor" href="#📝-小结" aria-label="Permalink to &quot;📝 小结&quot;">​</a></h2><ul><li>Next.js 是<strong>全栈框架</strong>,面试价值在于它同时覆盖了 SSR/SSG/ISR、缓存、BFF、部署三块,一个框架能撑起多个话题。</li><li>必读四章:渲染模式(1)、App Router(2)、数据获取与缓存(3、10)、Server Actions(4)——这是面试最高频的四个点。</li><li>必须记住 Next 15 的变化:<strong>fetch 默认不缓存</strong>,以及 <code>cookies/headers/searchParams</code> 会让路由退化为动态渲染。</li><li>心智模型一句话:<strong>App Router = RSC 默认服务端渲染 + 客户端组件按需下发</strong>,<code>&#39;use client&#39;</code> 是边界声明。</li><li>加分:能讲部署与缓存的<strong>实际踩坑</strong>(standalone 静态资源丢失、CDN 未按版本回切)。</li></ul>',6)])])}const u=a(o,[["render",l]]);export{h as __pageData,u as default};
